<div class="request"><h1>پیگیری درخواست طراحی</h1><?php if($request): ?><p>کد پیگیری: <b dir="ltr"><?= e($request['tracking']) ?></b></p><p>این کد را ذخیره کنید.</p><p class="notice">وضعیت: <?= e(['submitted'=>'ثبت‌شده','reviewing'=>'در حال بررسی','accepted'=>'پذیرفته','completed'=>'انجام‌شده','rejected'=>'رد یا نیازمند اصلاح'][$request['status']]??$request['status']) ?></p><?php else: ?><form method="get" action="/index.php"><input type="hidden" name="page" value="request-track"><label for="token">کد پیگیری</label><input id="token" name="token" required maxlength="64"><button class="primary">پیگیری</button></form><?php if(!empty($_GET['token'])): ?><p role="alert">درخواستی با این کد پیدا نشد.</p><?php endif ?><?php endif ?></div>
